      "Enrobage et finition",
      "QS Couverture Ocumaré 72% (Valrhona) à point",
      "Pour obtenir une qualité optimale d’enrobage, il est fondamental de respecter certains principes de travail et de contrôler rigoureusement l’hygrométrie qui doit être  inférieure à 60% et le laboratoire idéalement séparé en deux parties à température différente. La première partie à la température  de 24 à 27°C, servira à la fois de zone de stockage pour les intérieurs avant l’enrobage ainsi qu’à l’enrobage et le décor. La seconde partie sera réservée à la cristallisation des sablés à 16°C.",
      "Mettez à tempérer les sablés dans la zone d’enrobage (24/27°C) environ une heure avant, en préparation de l’enrobage. Déposez les « allumettes » sur le tapis en biais dans le but d’améliorer la finition du « pied ». Enrobez et faites écouler l’excédent de couverture à l’aide de la soufflerie et avec un peu de tapotage. A la sortie de la chaîne d’enrobage à 16°C, ramassez les sablés avec le papier et tirez-les sur plaques alu. Mettez en échelle et laissez cristalliser pendant 24 heures. Procédez au conditionnement.",
      "NB : Pour assurer la qualité optimale des sablés banane  au chocolat il est impératif qu’il soit enrobé le jour même de la cuisson.",
      "Emballage",
