      "Posez l’abaisse de pâte feuilletée sur une plaque de cuisson, saupoudrez l’abaisse avec le sucre semoule de manière uniforme et glissez-la dans le four chaud à 230°C, aussitôt baissé à 190°C, où la pâte cuira 20/25 minutes au total. Laissez-la d’abord cuire 10 minutes, puis couvrez-la d’une grille pour l’empêcher de lever excessivement et poursuivez la cuisson 8 minutes. Retirez la plaque du four, ôtez la grille, couvrez-la d’une feuille de papier siliconé sec, puis d’une seconde plaque de cuisson, identique à la première ; tournez  les deux plaques, sens dessus dessous, en les maintenant bien ensemble, sur le plan de travail ; retirez la plaque de cuisson supérieure et la feuille de papier qui ont servi au premier stade de la cuisson, le dessous se trouvant maintenant au-dessus, saupoudrez-le uniformément de sucre glace avant de la glisser au four à 250°C, où elle achèvera de cuire. Pendant les quelques minutes que durera le dernier tiers de la cuisson, le sucre glace va devenir jaune avant de fondre puis de caraméliser. Retirez la plaque du four : sa surface est lisse et brillante et, dessous, elle est mate et croquante, du fait de l’incrustation du sucre semoule dans la pâte en début de cuisson, sa texture est délicieuse.",
