    ingredients: [
      { nom: "sucre semoule", g: 80.0, pct: 61.5, role: "sucrant" },
      { nom: "sucre glace", g: 50.0, pct: 38.5, role: "sucrant" },
    ],
    procede: [
      "Posez l’abaisse de pâte feuilletée inversée sur une plaque de cuisson, saupoudrez-la de 80 g de sucre semoule de manière uniforme et glissez-la dans le four chaud (230°C), aussitôt baissé à 190°C, où la pâte cuira pendant 20/25 minutes en tout. Laissez-la d’abord cuire pendant 10 minutes, puis couvrez-la d’une grille pour l’empêcher de lever excessivement et poursuivez la cuisson pendant 8 minutes. Retirez la pâte du four, ôtez la grille, couvrez-la d’un papier cuisson sec, puis d’une seconde plaque, identique à la première ; retirez les deux plaques, sens dessus dessous, en les maintenant bien ensemble, sur le plan de travail ; retirez la première plaque et le papier qui ont servi à la pré cuisson de la pâte puis, le dessous se trouvant maintenant au-dessus, saupoudrez-la uniformément de sucre glace avant de la glisser au four à 250°C, où elle achèvera de cuire. Pendant les quelques minutes que durera le dernier tiers de la cuisson, le sucre va devenir jaune avant de fondre puis de caraméliser. Retirez la pâte du four : sa surface est lisse et brillante et, dessous, elle est mate et croquante, du fait de l’incrustation du sucre semoule dans la pâte en début de cuisson...sa texture est délicieuse.",
      "N.B : Ne pas poussez trop loin la cuisson de la pâte feuilletée caramélisée car cela peut donner un goût trop amer à votre gâteau.",
      "Bandes de pâte feuilletée inversée au fruit de la passion caramélisée",
      "Plaque de pâte feuilletée inversée au fruit de la passion caramélisée",
      "Pour les individuels : Dans la plaque de pâte feuilletée caramélisée, taillez trois bandes de 11 cm de largeur. Réservez.",
      "Pour les entremets : Dans la plaque de pâte feuilletée caramélisée, taillez des rectangles (11 x 17,5 cm pour les 3/4 pers ; 17,5 x 18 cm pour les 6/8 pers ; 17,5 x 24 cm pour les 10/12 pers.). Réservez.",
    ],
